with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw13_16_geo01_v1'), a as (select x.id,x.assessment_key from private.exam_prep_assessments x join cv on cv.id=x.content_version_id), m as (select x.content_key,x.question_id from private.exam_prep_question_content_meta x join cv on cv.id=x.content_version_id), w as (select x.id,x.task_key from private.exam_prep_written_tasks x join cv on cv.id=x.content_version_id), items(akey,ord,ckey,wkey,role,holdout) as (values
('p5_geo01_diagnostic',1,'P5GEO01-D01',null,'diagnostic',true),('p5_geo01_learning',1,'P5GEO01-L01',null,'learning',false),('p5_geo01_learning',2,'P5GEO01-L02',null,'learning',false),('p5_geo01_learning',3,'P5GEO01-L03',null,'learning',false),('p5_geo01_learning',4,null,'P5GEO01-W01','written',false),('p5_geo01_retest',1,'P5GEO01-R01',null,'retest',true),('p5_geo01_mixed',1,'P5GEO01-M01',null,'mixed',true))
